def parse_mark(text):
    mark = int(text)
    if mark < 0 or mark > 100:
        raise ValueError("mark must be 0 to 100")
    return mark

def total_marks(texts):
    total = 0
    for text in texts:
        total = total + parse_mark(text)
    return total

print(total_marks(["70", "150", "60"]))

